import React, { useEffect, useState } from 'react';
import { useNavigate, useParams, useSearchParams, Link } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { resumeApi, templateApi } from '../services/api';
import { downloadResume } from '../utils/downloadResume';

const emptyResume = {
  title: '', candidateName: '', headline: '', summary: '', contactEmail: '', contactPhone: '',
  address: '', location: '', linkedInUrl: '', portfolioUrl: '', skills: [], education: [], experience: [],
  visibleToRecruiters: false, templateId: null,
};

export default function ResumeBuilder() {
  const { id } = useParams();
  const isNew = id === 'new';
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const { user } = useAuth();

  const [resume, setResume] = useState(emptyResume);
  const [skillInput, setSkillInput] = useState('');
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState('');
  const [templates, setTemplates] = useState([]);

  useEffect(() => {
    templateApi.getAll().then((res) => setTemplates(res.data));
  }, []);

  useEffect(() => {
    if (!isNew) {
      resumeApi.getById(id)
        .then((res) => setResume({ ...emptyResume, ...res.data }))
        .catch(() => setError('Could not load resume.'));
    } else {
      // A template chosen from the Template Library arrives as ?template=<id>
      const templateParam = searchParams.get('template');
      const templateId = templateParam ? Number(templateParam) : null;
      setResume({
        ...emptyResume,
        candidateName: user?.fullName || '',
        contactEmail: user?.email || '',
        templateId,
      });
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [id, isNew, user]);

  const selectedTemplate = templates.find((t) => t.id === resume.templateId);

  const update = (field, value) => setResume({ ...resume, [field]: value });

  const addSkill = () => {
    if (skillInput.trim() && !resume.skills.includes(skillInput.trim())) {
      update('skills', [...resume.skills, skillInput.trim()]);
    }
    setSkillInput('');
  };

  const removeSkill = (skill) => update('skills', resume.skills.filter((s) => s !== skill));

  const addEducation = () => update('education', [...resume.education, {
    institution: '', degree: '', fieldOfStudy: '', startDate: '', endDate: '', gpa: '', displayOrder: resume.education.length,
  }]);

  const updateEducation = (index, field, value) => {
    const list = [...resume.education];
    list[index] = { ...list[index], [field]: value };
    update('education', list);
  };

  const removeEducation = (index) => update('education', resume.education.filter((_, i) => i !== index));

  const addExperience = () => update('experience', [...resume.experience, {
    company: '', jobTitle: '', startDate: '', endDate: '', current: false, description: '', displayOrder: resume.experience.length,
  }]);

  const updateExperience = (index, field, value) => {
    const list = [...resume.experience];
    list[index] = { ...list[index], [field]: value };
    update('experience', list);
  };

  const removeExperience = (index) => update('experience', resume.experience.filter((_, i) => i !== index));

  const handleSave = async () => {
    setSaving(true);
    setError('');
    try {
      if (isNew) {
        const res = await resumeApi.create(resume);
        navigate(`/resume/${res.data.id}`);
      } else {
        await resumeApi.update(id, resume);
        navigate('/dashboard');
      }
    } catch (err) {
      setError(err.response?.data?.message || 'Could not save resume.');
    } finally {
      setSaving(false);
    }
  };

  const handleDownload = () => {
    downloadResume(resume);
  };

  return (
    <div className="page-container" style={selectedTemplate ? { fontFamily: selectedTemplate.fontFamily } : undefined}>
      <div className="page-header">
        <h1>{isNew ? 'New Resume' : 'Edit Resume'}</h1>
        <button type="button" className="btn-secondary" onClick={handleDownload} title="Preview and download or print resume">
          📄 Download / Print PDF
        </button>
      </div>
      {error && <div className="error-banner">{error}</div>}

      <section className="form-section template-banner">
        {selectedTemplate ? (
          <>
            <p>
              Using template: <strong>{selectedTemplate.name}</strong>{' '}
              <span className="muted">({selectedTemplate.colorScheme}, {selectedTemplate.fontFamily})</span>
            </p>
            <Link to="/templates" className="btn-link">Change template</Link>
          </>
        ) : (
          <>
            <p className="muted">No template selected — this resume will use the default plain layout.</p>
            <Link to="/templates" className="btn-link">Choose a template</Link>
          </>
        )}
      </section>

      <section className="form-section">
        <h2>Resume Details</h2>
        <label>Resume Title (internal, e.g. "Frontend Dev - v2")</label>
        <input value={resume.title} onChange={(e) => update('title', e.target.value)} />
        <label>Headline</label>
        <input value={resume.headline} onChange={(e) => update('headline', e.target.value)} placeholder="e.g. Senior Software Engineer" />
        <label>Professional Summary</label>
        <textarea rows={4} value={resume.summary} onChange={(e) => update('summary', e.target.value)} />
      </section>

      <section className="form-section">
        <h2>Personal Details</h2>
        <div className="form-row">
          <div>
            <label>Full Name</label>
            <input value={resume.candidateName} onChange={(e) => update('candidateName', e.target.value)} placeholder="e.g. Priya Sharma" />
          </div>
          <div>
            <label>Email Address</label>
            <input value={resume.contactEmail} onChange={(e) => update('contactEmail', e.target.value)} placeholder="e.g. priya.sharma@example.com" />
          </div>
        </div>
        <div className="form-row">
          <div>
            <label>Phone Number</label>
            <input value={resume.contactPhone} onChange={(e) => update('contactPhone', e.target.value)} placeholder="e.g. +91 98765 43210" />
          </div>
          <div>
            <label>Location (City, Country)</label>
            <input value={resume.location} onChange={(e) => update('location', e.target.value)} placeholder="e.g. Chennai, India" />
          </div>
        </div>
        <div className="form-row">
          <div>
            <label>Street Address</label>
            <input value={resume.address} onChange={(e) => update('address', e.target.value)} placeholder="e.g. 12, Gandhi Street, T. Nagar" />
          </div>
        </div>
        <div className="form-row">
          <div>
            <label>LinkedIn URL</label>
            <input value={resume.linkedInUrl} onChange={(e) => update('linkedInUrl', e.target.value)} placeholder="e.g. https://linkedin.com/in/priyasharma" />
          </div>
          <div>
            <label>Portfolio / Website URL</label>
            <input value={resume.portfolioUrl} onChange={(e) => update('portfolioUrl', e.target.value)} placeholder="e.g. https://priyasharma.dev" />
          </div>
        </div>
      </section>

      <section className="form-section">
        <h2>Skills</h2>
        <div className="skill-input-row">
          <input
            value={skillInput}
            onChange={(e) => setSkillInput(e.target.value)}
            onKeyDown={(e) => e.key === 'Enter' && (e.preventDefault(), addSkill())}
            placeholder="Add a skill and press Enter"
          />
          <button type="button" onClick={addSkill}>Add</button>
        </div>
        <div className="skill-tags">
          {resume.skills.map((s) => (
            <span key={s} className="skill-tag">{s} <button onClick={() => removeSkill(s)}>&times;</button></span>
          ))}
        </div>
      </section>

      <section className="form-section">
        <h2>Education</h2>
        {resume.education.map((edu, i) => (
          <div className="entry-block" key={i}>
            <div className="form-row">
              <input placeholder="Institution" value={edu.institution} onChange={(e) => updateEducation(i, 'institution', e.target.value)} />
              <input placeholder="Degree" value={edu.degree} onChange={(e) => updateEducation(i, 'degree', e.target.value)} />
            </div>
            <div className="form-row">
              <input placeholder="Field of Study" value={edu.fieldOfStudy} onChange={(e) => updateEducation(i, 'fieldOfStudy', e.target.value)} />
              <input placeholder="GPA" value={edu.gpa} onChange={(e) => updateEducation(i, 'gpa', e.target.value)} />
            </div>
            <div className="form-row">
              <input placeholder="Start (e.g. 2021)" value={edu.startDate} onChange={(e) => updateEducation(i, 'startDate', e.target.value)} />
              <input placeholder="End (e.g. 2025)" value={edu.endDate} onChange={(e) => updateEducation(i, 'endDate', e.target.value)} />
            </div>
            <button className="btn-link danger" onClick={() => removeEducation(i)}>Remove</button>
          </div>
        ))}
        <button type="button" onClick={addEducation}>+ Add Education</button>
      </section>

      <section className="form-section">
        <h2>Experience</h2>
        {resume.experience.map((exp, i) => (
          <div className="entry-block" key={i}>
            <div className="form-row">
              <input placeholder="Company" value={exp.company} onChange={(e) => updateExperience(i, 'company', e.target.value)} />
              <input placeholder="Job Title" value={exp.jobTitle} onChange={(e) => updateExperience(i, 'jobTitle', e.target.value)} />
            </div>
            <div className="form-row">
              <input placeholder="Start (e.g. Jan 2022)" value={exp.startDate} onChange={(e) => updateExperience(i, 'startDate', e.target.value)} />
              <input placeholder="End (e.g. Present)" value={exp.endDate} onChange={(e) => updateExperience(i, 'endDate', e.target.value)} disabled={exp.current} />
            </div>
            <label className="checkbox-label">
              <input type="checkbox" checked={exp.current} onChange={(e) => updateExperience(i, 'current', e.target.checked)} />
              Currently working here
            </label>
            <label>Description (quantify achievements where possible)</label>
            <textarea rows={3} value={exp.description} onChange={(e) => updateExperience(i, 'description', e.target.value)} />
            <button className="btn-link danger" onClick={() => removeExperience(i)}>Remove</button>
          </div>
        ))}
        <button type="button" onClick={addExperience}>+ Add Experience</button>
      </section>

      <section className="form-section">
        <label className="checkbox-label">
          <input
            type="checkbox"
            checked={resume.visibleToRecruiters}
            onChange={(e) => update('visibleToRecruiters', e.target.checked)}
          />
          Make this resume visible to recruiters (FR7 candidate search)
        </label>
      </section>

      <div className="form-actions" style={{ display: 'flex', justifyContent: 'flex-end', gap: '12px' }}>
        <button type="button" className="btn-secondary" onClick={handleDownload}>
          Download / Print PDF
        </button>
        <button className="btn-primary" onClick={handleSave} disabled={saving}>
          {saving ? 'Saving…' : 'Save Resume'}
        </button>
      </div>
    </div>
  );
}
